window.STORY_CHAPTERS=window.STORY_CHAPTERS||{};window.STORY_CHAPTERS["22ea1f1a-a58f-5ebc-acc7-b470b05c100f"]={"id":"22ea1f1a-a58f-5ebc-acc7-b470b05c100f","scenes":[{"id":"0ed198b9-9fd9-5ef8-a794-d4e5abaa07c4","name":"После звонка","backgroundId":"171f06f6-3fb1-5491-aaa8-ae590f34ef16","characterId":"","emotionId":"","text":"Связь с Кустовой оборвалась. Серая папка осталась открытой на последней странице.","italic":false,"lines":[{"id":"9aa94172-e90c-5476-ab90-45107b215674","text":"Вчера вы спорили, кто сядет в директорское кресло. Сегодня я читаю, что со мной собирались что-то решить.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"52ec0a10-ba4b-5698-99d7-c358e6f7d371","text":"Я не писала эту фразу.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"56b7e939-85f4-5a7a-a842-72740d7f1077","text":"И я не писала. Но Кустовая каким-то образом увидела страницу.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"41088af7-7bcc-5888-9a63-db652f02e966","text":"Не давайте папке снова исчезнуть. В ней может быть ответ.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false}],"route":{"next":"","statId":"85c62c7f-e1cb-5d75-8309-b20a03bde953","operator":">=","value":1,"yes":"f1af4e97-dd63-5d56-91e0-f6aa3f7bbd82","no":"25888885-5f55-5cec-bc17-fe0818496a50"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"f1af4e97-dd63-5d56-91e0-f6aa3f7bbd82","name":"Старая копия","backgroundId":"b5806f1b-27b6-5d9e-9d30-7259eb2f74f6","characterId":"","emotionId":"","text":"Зоя сравнила последнюю страницу со своей копией. Приписки в ней не было.","italic":false,"lines":[{"id":"70e9cddc-12ea-5b25-9e2a-c43098857399","text":"Эту строку добавили позже. Значит, она не часть исходного плана.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"3407f878-b8cc-523f-9274-e340dffa6e84","text":"Или кто-то изменил копию.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"fea373c3-2fab-5484-8fff-d33b2982b2ac","text":"Мы не узнаем, пока не увидим документы целиком.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false}],"route":{"next":"4ea4ea20-facc-59bd-b4b0-1c11de338e6a","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"25888885-5f55-5cec-bc17-fe0818496a50","name":"Единственный экземпляр","backgroundId":"b5806f1b-27b6-5d9e-9d30-7259eb2f74f6","characterId":"","emotionId":"","text":"Копии страницы у Зои не было. Она могла судить только по тому, что лежало перед ней.","italic":false,"lines":[{"id":"7537114a-d7b2-5ce8-ab30-ba98aa0dd33d","text":"Кто бы это ни написал, я не собираюсь ждать, пока за меня всё решат.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"4ea4ea20-facc-59bd-b4b0-1c11de338e6a","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"4ea4ea20-facc-59bd-b4b0-1c11de338e6a","name":"Распоряжение Кустовой","backgroundId":"55112545-b524-57df-8146-6cd7dc39b658","characterId":"","emotionId":"","text":"Пришло сообщение Кустовой: после закрытия провести срочную проверку документов. Она приедет лично.","italic":false,"lines":[{"id":"2808526c-78cb-52f7-9716-e452e99f197b","text":"Если мы покажем ей документы, она сможет сама разобраться.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"3a3aaa4f-84da-5e5a-be47-0a2a8c9cfb14","text":"А если они останутся только у неё, мы больше не узнаем, что в них было.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false},{"id":"ebb52f23-70e8-535d-a4ac-43d0bb6ed8cf","text":"Тогда решим заранее, кто и что ей передаст.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"e037c55f-403e-523c-8532-a19a9eba0a5f","text":"Сделать дополнительную копию · 8 ✦","nextSceneId":"f660d0da-2b86-50e7-a0f4-4334a5eb8da6","money":0,"cost":8,"statId":"85c62c7f-e1cb-5d75-8309-b20a03bde953","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"ba716392-5759-5a8d-92f4-13c4db921827","text":"Доверить материалы Сергею","nextSceneId":"cd7b3cc9-9d5c-5aba-81cd-a157abe33f05","money":0,"cost":0,"statId":"70e6292a-851f-55e4-9669-caab2b491283","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"faef8aab-2cc5-53b8-814b-028c5579c6fc","text":"Сохранить деньги и ждать Кустовую","nextSceneId":"1fa03115-6d9f-5fcd-b098-0632735cb57c","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"f660d0da-2b86-50e7-a0f4-4334a5eb8da6","name":"Запасной экземпляр","backgroundId":"b5806f1b-27b6-5d9e-9d30-7259eb2f74f6","characterId":"","emotionId":"","text":"Зоя оплатила копию и убрала её отдельно от папки.","italic":false,"lines":[{"id":"5c0e94fe-c407-5eb5-bd0c-1b2b2092c7cf","text":"Теперь хотя бы один экземпляр не исчезнет вместе с чьими-то обещаниями.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"42be1ce9-5215-5358-9e90-019191e5ae46","text":"Запасная копия не остановит противостояние, но поможет сохранить доказательства.","characterId":"","emotionId":"","italic":false}],"route":{"next":"5500ba85-bff7-533e-9e3b-b3b5bcd3bad2","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"cd7b3cc9-9d5c-5aba-81cd-a157abe33f05","name":"Доверить Сергею","backgroundId":"b5806f1b-27b6-5d9e-9d30-7259eb2f74f6","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Возьмите эти материалы. Если с папкой что-то случится, хотя бы фотографии останутся у вас.","italic":false,"lines":[{"id":"e1442708-5120-5dc7-bae0-dfc4ad0e4f11","text":"Хорошо. Но я не собираюсь закрывать глаза на твоё участие.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false},{"id":"720473ed-38a2-5060-8a5b-c4df5a139de1","text":"Я и не прошу.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"5500ba85-bff7-533e-9e3b-b3b5bcd3bad2","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"1fa03115-6d9f-5fcd-b098-0632735cb57c","name":"Сохранить деньги","backgroundId":"171f06f6-3fb1-5491-aaa8-ae590f34ef16","characterId":"","emotionId":"","text":"Зоя решила пока не тратить звёздочки. Папка осталась на столе под взглядом всех четверых.","italic":false,"lines":[],"route":{"next":"5500ba85-bff7-533e-9e3b-b3b5bcd3bad2","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"5500ba85-bff7-533e-9e3b-b3b5bcd3bad2","name":"Два разговора","backgroundId":"171f06f6-3fb1-5491-aaa8-ae590f34ef16","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Прежде чем приедет Кустовая, хочу поговорить с каждой из вас отдельно.","italic":false,"lines":[{"id":"9e7f4087-52ab-5b24-ba27-2ea578ef3787","text":"Только недолго.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"09b975af-24ae-5dde-9c2f-ade061ccd8f3","text":"На этот раз никаких разговоров за спиной Зои.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"e5afc68e-fd4f-59ed-b0f1-39c050d19b74","text":"Сначала поговорить со Светланой Станиславовной","nextSceneId":"a17926d1-42e5-5968-9c13-86a561d5de10","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"37d3021b-29fc-5ade-8bff-ffe6003dc4be","text":"Сначала поговорить с Натальей","nextSceneId":"c60bb4d1-9b58-5590-a04b-2cc0b291cc03","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"a17926d1-42e5-5968-9c13-86a561d5de10","name":"Версия директора","backgroundId":"171f06f6-3fb1-5491-aaa8-ae590f34ef16","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Я хотела получить контроль над магазином. Но Наталья тоже знала больше, чем говорила.","italic":false,"lines":[{"id":"6edaceef-7016-50f6-9414-03454080e717","text":"Ты тоже знала обо мне ещё до мясокомбината.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"eab21203-a3ac-5715-b4f4-01b5eb6cc2fe","text":"Знала. Я должна была сказать раньше. Это не оправдывает того, что кто-то написал в конце папки.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"2ca38fa4-4749-50aa-9e02-dfee4cdace2e","text":"А что было бы после назначения?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"40e6d844-1a71-57ad-aa0e-ef70e77f0617","text":"Мы собирались решить, кому можно доверить дальнейшую работу. Я не собиралась решать за тебя.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false}],"route":{"next":"0bb264bd-0d33-5aff-bd27-a121958b7ee7","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"0bb264bd-0d33-5aff-bd27-a121958b7ee7","name":"Версия Натальи","backgroundId":"171f06f6-3fb1-5491-aaa8-ae590f34ef16","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"Светлана Станиславовна собирала сведения обо всех. Ей нужен был человек без должности, который окажется рядом с нами.","italic":false,"lines":[{"id":"8980f557-f0f4-51d3-bcb3-3cca9e83dc27","text":"А тебе зачем были старые документы магазина?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"31bc359c-a077-55cf-9871-7e1ad9e7e31e","text":"Я хотела знать, что она скрывает. Если бы спросила прямо, она бы их не показала.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"2871c272-fc67-53ef-976c-375849ebd3d6","text":"Обе истории объясняли часть происходящего. Но не почерк на последней странице.","characterId":"","emotionId":"","italic":false}],"route":{"next":"59545a36-da98-5225-b5cc-807f26b548df","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"c60bb4d1-9b58-5590-a04b-2cc0b291cc03","name":"Версия заместителя","backgroundId":"171f06f6-3fb1-5491-aaa8-ae590f34ef16","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"Светлана Станиславовна собирала сведения обо всех. После назначения она могла бы оставить нас без ответа.","italic":false,"lines":[{"id":"364e4c79-2c51-5ac1-8097-4bbf59ce3a5f","text":"А тебе зачем были старые документы магазина?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"3f8a990c-670a-5cd2-b648-d888b7447d12","text":"Я хотела знать, что она скрывает. Я не сказала тебе, потому что сама не была уверена.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"d30bdd29-171e-593a-99be-c5c4534de3c1","text":"Тогда перестань решать за меня, что мне знать.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"f79f7f48-06ab-5dcd-a8b3-a64fd13025ce","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"f79f7f48-06ab-5dcd-a8b3-a64fd13025ce","name":"Ответ С. С.","backgroundId":"171f06f6-3fb1-5491-aaa8-ae590f34ef16","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Я хотела получить контроль над магазином. Но не писала, что нужно расправиться с тобой.","italic":false,"lines":[{"id":"e55184a4-b02a-54cb-9755-9bdddba535d2","text":"Ты уже однажды говорила мне не всю правду.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"9da2e6d2-1d4f-5194-8536-7e69dc3d416a","text":"Да. Я должна была сказать раньше. Но и Наталья не рассказала, зачем изучала старые бумаги.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"03948580-e3e4-5874-98db-3a033612b528","text":"Обе истории объясняли часть происходящего. Но не почерк на последней странице.","characterId":"","emotionId":"","italic":false}],"route":{"next":"59545a36-da98-5225-b5cc-807f26b548df","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"59545a36-da98-5225-b5cc-807f26b548df","name":"Peugeot ждёт","backgroundId":"f2703370-10a3-5be8-9bdb-26b40921940c","characterId":"","emotionId":"","text":"Зоя вышла к Peugeot. Перед закрытием она ещё могла заправиться или оставить звёздочки при себе.","italic":false,"lines":[],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"c98a3152-9083-54ca-a23d-0ce687522ec0","text":"Заправить 2 единицы · 5 ✦","nextSceneId":"2175261a-1666-5992-b70f-e495cdf9fe90","money":0,"cost":5,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":2,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"8aa1b1a7-479a-58e5-941c-940b2d5fce5e","text":"Не тратить звёздочки","nextSceneId":"9bf48ce5-a939-51c3-adaf-e81eb106380d","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"2175261a-1666-5992-b70f-e495cdf9fe90","name":"Топливо в запасе","backgroundId":"f2703370-10a3-5be8-9bdb-26b40921940c","characterId":"","emotionId":"","text":"Зоя проверила бак. Теперь она могла выбрать дорогу на машине, если потребуется.","italic":false,"lines":[{"id":"48b1eb62-e50d-53e3-bfcc-c6290d7198c9","text":"На этот раз я хочу сама решить, когда уехать.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"438cd607-51f0-5585-b976-663fc325d5ff","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"9bf48ce5-a939-51c3-adaf-e81eb106380d","name":"Оставить деньги","backgroundId":"f2703370-10a3-5be8-9bdb-26b40921940c","characterId":"","emotionId":"","text":"Зоя убрала кошелёк. Возможность уехать на Peugeot будет зависеть от остатка топлива.","italic":false,"lines":[],"route":{"next":"438cd607-51f0-5585-b976-663fc325d5ff","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"438cd607-51f0-5585-b976-663fc325d5ff","name":"Предложение Сергея","backgroundId":"e480419c-c994-5e05-ac55-e4691c06eb6c","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","text":"Кустовая действительно едет. Но документы не должны оказаться только у неё.","italic":false,"lines":[{"id":"97114a6d-1cbe-5808-90cf-74f2f0b675bc","text":"Ты готов встретить её со мной?","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"b574a320-ee86-5de0-b5af-a15cf6c9bd74","text":"Да. Я помогу, но не буду делать вид, будто ты не участвовала в этом плане.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false}],"route":{"next":"","statId":"70e6292a-851f-55e4-9669-caab2b491283","operator":">=","value":1,"yes":"3a9d7b28-f842-5251-bf8e-b540d96dd5f7","no":"6a48ca18-0a7b-510c-8e75-0dcf333ad82b"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"3a9d7b28-f842-5251-bf8e-b540d96dd5f7","name":"Запасные снимки","backgroundId":"e480419c-c994-5e05-ac55-e4691c06eb6c","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","text":"Ты хотя бы пыталась разобраться. Возьми мой телефон: фотографии будут у тебя.","italic":false,"lines":[{"id":"ec8c5b47-3ede-5de0-bf6d-5bff1d01e149","text":"Спасибо. Впервые эта история становится немного похожей на сотрудничество.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"95b21c8d-59f6-5e32-9412-bb535d0dec09","text":"Сохранить фотографии","nextSceneId":"83a1481f-0913-50f9-890a-09be8f5d62dc","money":0,"cost":0,"statId":"85c62c7f-e1cb-5d75-8309-b20a03bde953","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"6a48ca18-0a7b-510c-8e75-0dcf333ad82b","name":"Осторожность Сергея","backgroundId":"e480419c-c994-5e05-ac55-e4691c06eb6c","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","text":"Фотографии останутся у меня. После того, что случилось, я не уверен, кому их можно отдавать.","italic":false,"lines":[{"id":"4050b8c6-5f17-5743-91bb-933f3b3618d5","text":"Тогда держись рядом. Я не хочу ещё одного пропавшего человека.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"83a1481f-0913-50f9-890a-09be8f5d62dc","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"83a1481f-0913-50f9-890a-09be8f5d62dc","name":"После закрытия","backgroundId":"29a09ad5-3f3f-5a21-a937-b4aa4996360b","characterId":"","emotionId":"","text":"После закрытия часть света в магазине погасла. Зоя позвонила Кустовой, но связи не было.","italic":false,"lines":[{"id":"f61c25dd-dfb2-5647-8d7f-413b995d2cf7","text":"Сергей пошёл к служебному входу. Он не отвечает.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"4dd282ee-d4a5-509e-841f-9bb87abff4b3","text":"Папка тоже исчезла со стола.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"5de24e63-a9d2-5a72-bdce-bc0ba97fe349","text":"Только не говорите, что теперь будем ждать, пока всё само найдётся.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"d0ea8bbb-bacf-57d8-a559-db470f4fc260","text":"Пойти со Светланой Станиславовной","nextSceneId":"c8db2d35-6cc4-5fe6-8f82-ef2042c9915b","money":0,"cost":0,"statId":"8f8e4bde-4e08-578d-9292-6b002292f032","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"ec4c296b-ed5a-51be-9c88-d7d750d4e932","text":"Пойти с Натальей","nextSceneId":"2a5f90b7-c564-5560-bc75-d9ee6410df26","money":0,"cost":0,"statId":"ff79c195-0c9e-569a-87c5-e009ff36d05a","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"82216f67-8ec8-5387-8876-8b8d5075c624","text":"Найти Сергея самостоятельно","nextSceneId":"de7e665c-9550-59b0-b982-e2fd2ef6a2b0","money":0,"cost":0,"statId":"439a5762-6ae1-49cb-9f20-164fbb7584e2","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"439a5762-6ae1-49cb-9f20-164fbb7584e2","operator":">=","value":2}},{"id":"b89944a4-b958-5924-99ca-38498e8d30ac","text":"Поехать на Peugeot за помощью · 1 топливо","nextSceneId":"dfcb6c4f-e0e0-5d8e-b14d-6a9c660220bf","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":1,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"c8db2d35-6cc4-5fe6-8f82-ef2042c9915b","name":"Вместе с С. С.","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Я знаю этот коридор. Держись рядом.","italic":false,"lines":[{"id":"fd51afbb-0db0-53c1-8dec-d3ada887b215","text":"Я держусь рядом, пока ты отвечаешь на вопросы.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"000a4c4d-3de7-5ed2-953b-e8614a0bc871","text":"Из-за двери послышался звук упавшего телефона.","characterId":"","emotionId":"","italic":false}],"route":{"next":"9e188dd9-f6e4-5efb-b157-30ccf792b8bd","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"2a5f90b7-c564-5560-bc75-d9ee6410df26","name":"Вместе с Натальей","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"Сюда ведёт служебный проход. Если Сергей здесь, мы его найдём.","italic":false,"lines":[{"id":"74b35318-8fde-5bc2-84cf-a743a004b236","text":"Надеюсь, раньше папки.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"25cd41fc-3e26-5a0b-9cb0-6840f797bfb2","text":"За дверью кто-то попытался позвать на помощь.","characterId":"","emotionId":"","italic":false}],"route":{"next":"9e188dd9-f6e4-5efb-b157-30ccf792b8bd","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"de7e665c-9550-59b0-b982-e2fd2ef6a2b0","name":"Поиск Сергея","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Зоя прошла по служебному коридору одна и увидела свет из-под двери.","italic":false,"lines":[{"id":"d6511d89-0406-579e-8985-47b49bdacaa7","text":"Сергей? Если это шутка, я заранее не смеюсь.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"66b46f6d-b97d-5fd0-a459-553ff1ed06d7","text":"Из комнаты раздался его голос.","characterId":"","emotionId":"","italic":false}],"route":{"next":"9e188dd9-f6e4-5efb-b157-30ccf792b8bd","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"dfcb6c4f-e0e0-5d8e-b14d-6a9c660220bf","name":"Помощь снаружи","backgroundId":"f2703370-10a3-5be8-9bdb-26b40921940c","characterId":"","emotionId":"","text":"Зоя отъехала на Peugeot и поймала связь. Кустовая сообщила, что уже рядом.","italic":false,"lines":[{"id":"b6f8995e-feee-5bc0-a8c2-b444764f49b3","text":"Тогда приезжайте быстрее. Здесь всё идёт совсем не по плану.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"2835a2af-6487-55b8-83ec-f3a08b9e51c9","text":"Она вернулась к служебному входу: оставлять остальных одних она не собиралась.","characterId":"","emotionId":"","italic":false}],"route":{"next":"9e188dd9-f6e4-5efb-b157-30ccf792b8bd","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"9e188dd9-f6e4-5efb-b157-30ccf792b8bd","name":"Кто сделал ход","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Сергей нашёлся в служебной комнате. Он был жив, но телефон и документы исчезли.","italic":false,"lines":[{"id":"57c8b01c-ac33-5efa-91ab-5b003fb9221d","text":"Одна из них забрала папку. Я не успел понять, что она собирается делать.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false},{"id":"92e3d600-6306-56fa-a16c-5a7498f39887","text":"Зоя вспомнила, кого она поддерживала с самого начала.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"11bd0163-2973-589d-b646-1502801c746a","operator":">","value":0,"yes":"9b5e4d40-b09c-5307-a56b-d03c7160afc7","no":"cf8f7af1-fcdd-517b-9f17-ac76c55cf9c9"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"cf8f7af1-fcdd-517b-9f17-ac76c55cf9c9","name":"Прежнее решение","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Вечер у доски и выбор папки казались теперь особенно важными.","italic":false,"lines":[],"route":{"next":"","statId":"11bd0163-2973-589d-b646-1502801c746a","operator":"\u003c","value":0,"yes":"c2bfa383-dfce-5431-8119-2b3a7ac18655","no":"5b767bec-2f15-5830-bea4-9d852533d16c"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"5b767bec-2f15-5830-bea4-9d852533d16c","name":"Кому досталась папка","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Если Зоя не выбирала союзницу, последним определяющим решением стало то, кому она доверила папку.","italic":false,"lines":[],"route":{"next":"","statId":"2762c1b9-0f9c-5ff8-b3be-8cfc5e0e08a8","operator":"==","value":3,"yes":"9b5e4d40-b09c-5307-a56b-d03c7160afc7","no":"c2bfa383-dfce-5431-8119-2b3a7ac18655"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"9b5e4d40-b09c-5307-a56b-d03c7160afc7","name":"Наталья и папка","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"После назначения Светлана Станиславовна получила всё. Я должна была остаться рядом и отвечать за её решения?","italic":false,"lines":[{"id":"653faae8-14fc-533e-b72f-9bdcb5075653","text":"Это не причина угрожать мне.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"bfc83807-0c09-56df-a773-d28a94dfa0ec","text":"Если папка окажется у Кустовой, вы обе расскажете свою версию. Моей никто не поверит.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"b020ab1c-8e54-50d2-9458-8b90adbc5c67","text":"Наталья схватила Зою за руку и преградила путь к выходу. С. С. встала между ними.","characterId":"","emotionId":"","italic":false},{"id":"93f6ff12-ed8e-517b-b1cf-b71381e8cd42","text":"Отпусти её. Она не должна была оказаться здесь.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"acfd0074-e658-5a78-9f2a-52fbbacf3620","text":"Но оказалась. Благодаря тебе.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"36dd5e55-90fb-5ab0-a4ec-2abaf544b9dc","text":"Противостоять Наталье","nextSceneId":"63eef15d-b271-5f13-bf42-e6bd9cc6c71c","money":0,"cost":0,"statId":"b641c620-e6cc-59ab-b9de-3d06a8491afa","statChange":1,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"c2bfa383-dfce-5431-8119-2b3a7ac18655","name":"Светлана Станиславовна и папка","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Ты видела достаточно, чтобы передать папку Сергею или Кустовой. Я не могу позволить тебе уйти с ней.","italic":false,"lines":[{"id":"02e90f79-122c-54f8-9231-33171ec0e550","text":"А я не могу позволить тебе снова решать за меня.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"a1870163-7f47-588a-b016-2acb0f4c5e1f","text":"Светлана Станиславовна удержала папку и преградила выход. Наталья встала между ней и Зоей.","characterId":"","emotionId":"","italic":false},{"id":"4369c3c5-ec4f-5afd-b4b2-3de8c9191f56","text":"Ты хотела должность и получила её. Зою ты не получишь.","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","italic":false},{"id":"2003cb91-ee00-5c2d-937f-80d100f30aec","text":"Отойди. Ты не знаешь всего.","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","italic":false},{"id":"56a7e68b-db90-5523-8283-3dcd8c028ef3","text":"Так расскажи. Пока ещё можно.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"dbda2ef2-f990-588c-bdff-c284e90e488c","text":"Противостоять Светлане Станиславовне","nextSceneId":"63eef15d-b271-5f13-bf42-e6bd9cc6c71c","money":0,"cost":0,"statId":"b641c620-e6cc-59ab-b9de-3d06a8491afa","statChange":-1,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"63eef15d-b271-5f13-bf42-e6bd9cc6c71c","name":"Последнее решение","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Папка оказалась у Зои. Одна женщина пыталась остановить её, другая стояла рядом. Сергей добирался до телефона.","italic":false,"lines":[{"id":"fc5b5265-03b8-538e-9d9a-7bb08c66e8cb","text":"Никакой куш не стоит ещё одной жизни. Но я не отдам вам право решить за меня.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"a12d65bd-dcc3-5d99-9bae-08f40ed03d9d","text":"Попытаться остановить её словами","nextSceneId":"eae9a36f-af20-5119-b9f9-aadd2b63766d","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"f98cb989-552e-4ec1-bbb1-9e4839c49d0e","operator":">=","value":2}},{"id":"86f6ff27-36ad-5c87-8038-55e624d2b2eb","text":"Позвать Сергея на помощь","nextSceneId":"1d1fabc7-dc61-5613-a8ba-26699e3fe3d1","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"70e6292a-851f-55e4-9669-caab2b491283","operator":">=","value":1}},{"id":"4b683872-3a8a-5760-9d27-a58551a263c9","text":"Защитить союзницу собой","nextSceneId":"689354c6-5d99-535c-bb14-e32c33ef76d2","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"439a5762-6ae1-49cb-9f20-164fbb7584e2","operator":">=","value":2}},{"id":"93c2c974-d930-5d3d-a3dd-8bcce3738b06","text":"Уйти с документами на Peugeot · 1 топливо","nextSceneId":"25bca543-e5da-5ed3-9c07-95ed1592c4c4","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":1,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"24514fd3-3622-54b1-9076-ae3b1392f87a","text":"Применить силу, чтобы выжить","nextSceneId":"c885a110-9fdb-588c-b491-271baf831b1e","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"f4434394-cffd-56f1-9d8d-b3b6efe3f82f","text":"Отступить без документов","nextSceneId":"7f6d34a8-1d0b-549e-b216-86b88b271fa5","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"eae9a36f-af20-5119-b9f9-aadd2b63766d","name":"Последний разговор","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Ты всё ещё можешь остановиться. Я расскажу правду, но не позволю тебе уничтожить всё, что между нами было.","italic":false,"lines":[{"id":"61e766b4-1e8c-57b4-9fcb-d61fa06e37b3","text":"Женщина замерла. Второй удалось отвести Зою к двери, а Сергей наконец поднял телефон.","characterId":"","emotionId":"","italic":false},{"id":"5a684fcd-9c45-5a3e-a0ce-215b51b2bf8b","text":"Кустовая уже здесь. Пусть теперь документы прочитает не один человек.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false}],"route":{"next":"23f3d6be-96d8-5c55-8435-0e1a7487a66a","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"1d1fabc7-dc61-5613-a8ba-26699e3fe3d1","name":"Помощь Сергея","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","text":"Сергей, сейчас!","italic":false,"lines":[{"id":"49805a4c-cd57-57fe-83c6-a86a95d23340","text":"Я рядом. Отойди от двери.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false},{"id":"e107ce68-7c0d-5e7c-832f-81e5b0330809","text":"Сергей помог Зое выбраться из комнаты. Вторая женщина удержала нападавшую до приезда Кустовой.","characterId":"","emotionId":"","italic":false}],"route":{"next":"23f3d6be-96d8-5c55-8435-0e1a7487a66a","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"23f3d6be-96d8-5c55-8435-0e1a7487a66a","name":"Правда остаётся","backgroundId":"b5806f1b-27b6-5d9e-9d30-7259eb2f74f6","characterId":"","emotionId":"","text":"Кустовая прибыла вместе с людьми, вызванными Сергеем. Документы сохранились, и теперь каждый должен был объяснить свою часть истории.","italic":false,"lines":[{"id":"6a5145d0-be8d-54ee-8b97-8ba49c2c9b35","text":"Я расскажу всё. В том числе о том, что сделала сама.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"b007f1ed-f0ec-52d0-b8f4-2c57b1aaa16f","text":"Никто не погиб. «Большой куш» закончился не так, как рассчитывала любая из сторон.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"287ccf5d-1870-5cb3-a1c5-eb1e193f39f1","text":"Продолжить","nextSceneId":"bf5094fd-9128-5a5e-a858-e70896ba72e8","money":0,"cost":0,"statId":"0f291241-ac62-56de-9bec-06f7da7ad0d3","statChange":1,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"25bca543-e5da-5ed3-9c07-95ed1592c4c4","name":"Дорога за помощью","backgroundId":"f2703370-10a3-5be8-9bdb-26b40921940c","characterId":"","emotionId":"","text":"Зоя добралась до Peugeot и потратила последнее необходимое топливо, чтобы встретить Кустовую у въезда.","italic":false,"lines":[{"id":"0e2c438b-eacc-5346-9fd7-982e113c90a1","text":"Внутри остались люди. Нам нужна помощь сейчас.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"d98f6a61-840d-5ae3-a16a-afdafed7ce0f","text":"Что удалось сохранить из документов?","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"85c62c7f-e1cb-5d75-8309-b20a03bde953","operator":">=","value":1,"yes":"40e1181d-129e-5bb0-a8dc-f522b66b4c38","no":"e0739875-54da-502a-94bd-f0236905a883"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"40e1181d-129e-5bb0-a8dc-f522b66b4c38","name":"Доказательства в копии","backgroundId":"f2703370-10a3-5be8-9bdb-26b40921940c","characterId":"","emotionId":"","text":"У Зои была копия документов. Кустовая увидела её и вызвала помощь, не дожидаясь объяснений.","italic":false,"lines":[{"id":"c6bcb849-c4a6-56dc-9ef6-718495b96fe3","text":"Зоя вернулась вместе с ней. Противостояние удалось остановить без гибели.","characterId":"","emotionId":"","italic":false}],"route":{"next":"23f3d6be-96d8-5c55-8435-0e1a7487a66a","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"e0739875-54da-502a-94bd-f0236905a883","name":"Возвращение без копии","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Пока Зоя искала помощь, папка пропала. Вернувшись, она увидела, что союзница защитила Сергея, но сама получила смертельное ранение.","italic":false,"lines":[{"id":"6f8805e4-68bd-5921-9191-7ef27a1eacbd","text":"Я должна была вернуться раньше.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"1c2a9975-48da-5bc3-a783-43be6bf9fd82","text":"Ты вернулась с помощью. Иначе мы могли бы не выбраться никто.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"cce6ce94-95cd-542a-afa8-f8a6401b3ba1","text":"Продолжить","nextSceneId":"b82afbf5-2621-5660-8371-15140b578924","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"689354c6-5d99-535c-bb14-e32c33ef76d2","name":"Защитить союзницу","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Зоя шагнула между женщинами. В суматохе союзница оттолкнула её к двери и приняла удар на себя.","italic":false,"lines":[{"id":"ff795fdb-b858-5eb5-a347-444d3d520501","text":"Нет! Мы же могли остановиться!","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"84ea1bc3-24e7-505b-a07c-a05830f88433","text":"Зоя, сюда. Помощь уже едет.","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false},{"id":"81f88353-1c51-5534-b3bd-dcf6bd3483f6","text":"Остановить трагедию полностью не удалось.","characterId":"","emotionId":"","italic":false}],"route":{"next":"b82afbf5-2621-5660-8371-15140b578924","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"b82afbf5-2621-5660-8371-15140b578924","name":"Цена спасения","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Зоя держала за руку женщину, которая в последний момент выбрала защитить её.","italic":false,"lines":[],"route":{"next":"","statId":"b641c620-e6cc-59ab-b9de-3d06a8491afa","operator":">","value":0,"yes":"d9a37559-2e2d-5ee0-8ca6-081ce2c388b2","no":"8b8a70d2-2075-5c9d-ad3b-91c0d6a89f49"},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"d9a37559-2e2d-5ee0-8ca6-081ce2c388b2","name":"Светлана Станиславовна","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"c15323c4-79bc-4b5d-868f-fff59ea61a0b","emotionId":"fdf2ff59-2e09-59fc-a1ba-d3f557781c3a","text":"Я слишком долго решала за других. Прости меня.","italic":false,"lines":[{"id":"fd902603-1336-5155-b61c-ee9488a51903","text":"Не говори так. Мы вызвали помощь.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"e75105c2-3db5-54a7-867a-73fbc654bdc9","text":"Светлана Станиславовна не ответила. Наталью остановили, когда приехала Кустовая.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"5c3d1ff3-2433-5145-a627-afbe46d47273","text":"Продолжить","nextSceneId":"74b98dfc-3773-5ca4-8877-4e46a811eacd","money":0,"cost":0,"statId":"0f291241-ac62-56de-9bec-06f7da7ad0d3","statChange":2,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"8b8a70d2-2075-5c9d-ad3b-91c0d6a89f49","name":"Наталья","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"92f40577-c7d5-4e6e-97c6-6081558bb263","emotionId":"f7ce1053-2001-4b91-980e-80208645e976","text":"Хотела, чтобы мы начали всё по-другому.","italic":false,"lines":[{"id":"4f6e53ea-c9f3-5073-ab5c-c80b17427a49","text":"Не говори так. Помощь уже едет.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"a30456c9-5605-552b-939e-f64afc6310a7","text":"Наталья не ответила. Светлану Станиславовну остановили, когда приехала Кустовая.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"81856aaa-9204-51b0-96c9-b1fac4308102","text":"Продолжить","nextSceneId":"74b98dfc-3773-5ca4-8877-4e46a811eacd","money":0,"cost":0,"statId":"0f291241-ac62-56de-9bec-06f7da7ad0d3","statChange":2,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"c885a110-9fdb-588c-b491-271baf831b1e","name":"Цена силы","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Пытаясь освободиться, Зоя применила силу. Нападавшая упала и больше не поднялась.","italic":false,"lines":[{"id":"ab41cac9-5dec-5cc7-ab3a-a2a08cf022a7","text":"Зоя... что ты сделала?","characterId":"eb27223c-ac29-51bb-a89f-2aa688ebd4da","emotionId":"be343c0b-afec-5f4a-a21b-355486689145","italic":false},{"id":"d99c88e1-9a17-53f1-915c-6771b2e10735","text":"Я хотела, чтобы это закончилось.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"ca3366a1-10af-5aa9-a575-005b339a8674","text":"Доказательства были рядом. Теперь ей нужно было решить, что рассказать о случившемся.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"816993ad-a455-5375-80e9-740280c5732e","text":"Скрыть случившееся и сохранить план","nextSceneId":"c8013191-4bab-5ff6-9f6c-dadf9b32f5ba","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}},{"id":"cd938c85-540c-51bd-8f14-32acee46412e","text":"Рассказать Кустовой правду","nextSceneId":"5578c13a-7dd1-569e-ae72-d3dde7c1c76e","money":0,"cost":0,"statId":"","statChange":0,"extraStatId":"","extraStatChange":0,"important":true,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"5578c13a-7dd1-569e-ae72-d3dde7c1c76e","name":"Признание","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Зоя не стала скрывать произошедшее. Когда приехала Кустовая, она отдала документы и рассказала всё.","italic":false,"lines":[{"id":"dfb00a3d-72ae-5dd1-b1e0-ada5f8195247","text":"Правда сохранилась, но жизнь человека вернуть было невозможно. Союзница больше не могла оставаться рядом с Зоей.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"42e22624-8316-5558-be6a-d010dd435b16","text":"Продолжить","nextSceneId":"74b98dfc-3773-5ca4-8877-4e46a811eacd","money":0,"cost":0,"statId":"0f291241-ac62-56de-9bec-06f7da7ad0d3","statChange":2,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"c8013191-4bab-5ff6-9f6c-dadf9b32f5ba","name":"Сохранить план","backgroundId":"17ba0c6f-2812-5fc4-9ade-49a1798f77b7","characterId":"","emotionId":"","text":"Зоя спрятала документы и убедила остальных, что история должна остаться между ними.","italic":false,"lines":[{"id":"3bb0e97e-4e51-5530-8b4d-1a747caf4420","text":"Мы уже зашли слишком далеко, чтобы сейчас всё потерять.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"f550d763-602b-5a81-b7d6-460ab32f2107","text":"Сергей больше ей не доверял. Союзница ушла. Но кресло и папка остались.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"68cb24d3-0cef-5a61-8f2b-cc9e71732047","text":"Продолжить","nextSceneId":"c39cd1c6-7b8d-59fd-949c-ed56aed71602","money":0,"cost":0,"statId":"0f291241-ac62-56de-9bec-06f7da7ad0d3","statChange":4,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"7f6d34a8-1d0b-549e-b216-86b88b271fa5","name":"Без защиты","backgroundId":"861a74de-90cc-5975-89a4-8b8643f56211","characterId":"","emotionId":"","text":"Зоя отступила, оставив папку. Прежде чем она добралась до двери, нападавшая закрыла ей путь.","italic":false,"lines":[{"id":"c3b9f219-1fba-58eb-a5f2-df94d1e73497","text":"Подожди. Я не заберу документы.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"272a9f66-0e93-5c88-a9da-2e3da8efa881","text":"Кустовая приехала слишком поздно, чтобы остановить трагедию. Сергей сохранил только фотографии части документов.","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[{"id":"2aac560e-7e9c-5bd4-9faa-95b42b3ab253","text":"Продолжить","nextSceneId":"66ded5a7-466b-57d8-8a5d-64ca85cae617","money":0,"cost":0,"statId":"0f291241-ac62-56de-9bec-06f7da7ad0d3","statChange":3,"extraStatId":"","extraStatChange":0,"important":false,"fuelCost":0,"fuelGain":0,"condition":{"statId":"","operator":">=","value":0,"yes":"","no":""},"requirement":{"statId":"","operator":">=","value":0}}]},{"id":"bf5094fd-9128-5a5e-a858-e70896ba72e8","name":"Своя жизнь","backgroundId":"260ce3b6-07e8-5fb4-9a0c-1b22ba2f49bf","characterId":"","emotionId":"","text":"Утром Зоя вышла из дома и раскрыла газету. В ней была короткая заметка: «Порой один выбор меняет то, что произойдёт завтра».","italic":false,"lines":[{"id":"ef7eaa44-ae1c-5ada-9d00-f78ef861a022","text":"Наконец-то в газете написали что-то полезное.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"e90543c0-bf5d-5f95-a19e-39687c32544c","text":"Светлана Станиславовна и Наталья отвечали за свои решения. Зоя тоже рассказала свою часть истории — и получила возможность начать заново.","characterId":"","emotionId":"","italic":false},{"id":"01ca2c90-4eeb-5eb6-b12f-71aaaaba9801","text":"КОНЦОВКА 1 ИЗ 4 · СВОЯ ЖИЗНЬ","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"74b98dfc-3773-5ca4-8877-4e46a811eacd","name":"Цена свободы","backgroundId":"260ce3b6-07e8-5fb4-9a0c-1b22ba2f49bf","characterId":"","emotionId":"","text":"Зоя выжила, но осталась без человека, который попытался её защитить. Разбирательство ещё продолжалось.","italic":false,"lines":[{"id":"2f0dcd1f-2403-568c-a3c4-9e468685340b","text":"Она положила на сиденье Peugeot фотографию и долго не заводила машину.","characterId":"","emotionId":"","italic":false},{"id":"dd8abd74-2e61-58b4-910d-78786622cbf1","text":"Я не забуду, что ты сделала.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"474e455f-ae5d-52a1-9039-1a43072d6f52","text":"КОНЦОВКА 2 ИЗ 4 · ЦЕНА СВОБОДЫ","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"66ded5a7-466b-57d8-8a5d-64ca85cae617","name":"Большой куш","backgroundId":"17ba0c6f-2812-5fc4-9ade-49a1798f77b7","characterId":"","emotionId":"","text":"Сергей сохранил часть фотографий и продолжил рассказывать о случившемся. Зоя до утра не дожила.","italic":false,"lines":[{"id":"b298ae3b-148d-56dd-988e-093be7534489","text":"От плана осталась серая папка, в которой недоставало нескольких страниц.","characterId":"","emotionId":"","italic":false},{"id":"f185f46c-4786-564d-8867-4a4841435989","text":"КОНЦОВКА 3 ИЗ 4 · БОЛЬШОЙ КУШ","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]},{"id":"c39cd1c6-7b8d-59fd-949c-ed56aed71602","name":"На её месте","backgroundId":"17ba0c6f-2812-5fc4-9ade-49a1798f77b7","characterId":"","emotionId":"","text":"Зоя осталась в кабинете одна. На столе лежала серая папка; телефон снова зазвонил. На экране — «Кустовая».","italic":false,"lines":[{"id":"eabf2e8f-c61e-5dca-a8af-fb322f3a9936","text":"Да, слушаю.","characterId":"8d8e3253-7fc4-444b-9204-4f966dbfc9ad","emotionId":"037ab120-3416-4110-85f0-e19b5db85033","italic":false},{"id":"1096a7d7-4121-5df4-ad4c-8b3dc3364e5e","text":"Она получила доступ к плану и деньгам. Но человека, который верил ей без оговорок, рядом больше не было.","characterId":"","emotionId":"","italic":false},{"id":"1559806e-6a87-53c5-a227-a85bcbf5203d","text":"КОНЦОВКА 4 ИЗ 4 · НА ЕЁ МЕСТЕ","characterId":"","emotionId":"","italic":false}],"route":{"next":"","statId":"","operator":">=","value":0,"yes":"","no":""},"frame":{"x":50,"scale":100,"bgX":50,"bgY":50},"choices":[]}]};
